def skill():
    tot = 0
    for k in range(1, 4):
        for l in range(1, 3):
            if k + l <= 4:
                tot += binomial(4, k) * binomial(4 - k, l) * binomial(2, k - 1) * binomial(1, l - 1)
    return tot

def standard():
    from sympy.utilities.iterables import multiset_permutations
    return sum(1 for p in multiset_permutations("RRRBBWWW") if all({p[i], p[i + 1]} != {"R", "B"} for i in range(7)))

def unique():
    return [standard()]
